template<typename T>
struct Policy {
    static constexpr int calculate(int x) { return x * 10; }
};

// Compile-Time Polymorphism: Specialization
// Compiler creates a unique, optimized function body for this type
template<>
struct Policy<double> {
    static constexpr int calculate(int x) { return x + 50; }
};

// Usage avoids runtime VTable lookup entirely
constexpr int v1 = Policy<int>::calculate(2);      // Instantiation 1: 20
constexpr int v2 = Policy<double>::calculate(2);   // Instantiation 2: 52

// Result: Zero runtime overhead / Dynamic Dispatch eliminated
// Contrast: Requires static knowledge of types
// (vs virtual functions: types known only at runtime)
